def compare_versions(a: str, b: str) -> int:
    def parse_version(v: str) -> tuple:
        # Remove build metadata (everything after +)
        v = v.split('+')[0]

        # Split into core version and pre-release
        if '-' in v:
            core, prerelease = v.split('-', 1)
            prerelease_ids = prerelease.split('.')
        else:
            core = v
            prerelease_ids = None

        # Parse core version (MAJOR.MINOR.PATCH)
        parts = core.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        return (major, minor, patch, prerelease_ids)

    def compare_prerelease(pre_a, pre_b) -> int:
        # If both have no pre-release, they're equal (in terms of pre-release)
        if pre_a is None and pre_b is None:
            return 0
        # Version without pre-release has higher precedence
        if pre_a is None:
            return 1
        if pre_b is None:
            return -1

        # Both have pre-releases, compare identifiers
        for i in range(max(len(pre_a), len(pre_b))):
            if i >= len(pre_a):
                # pre_a has fewer identifiers, so it has lower precedence
                return -1
            if i >= len(pre_b):
                # pre_b has fewer identifiers, so pre_a has higher precedence
                return 1

            id_a = pre_a[i]
            id_b = pre_b[i]

            # Check if identifiers are numeric
            is_numeric_a = id_a.isdigit()
            is_numeric_b = id_b.isdigit()

            # Numeric identifiers are compared numerically
            if is_numeric_a and is_numeric_b:
                num_a = int(id_a)
                num_b = int(id_b)
                if num_a < num_b:
                    return -1
                elif num_a > num_b:
                    return 1
            # Numeric identifier has lower precedence than non-numeric
            elif is_numeric_a:
                return -1
            elif is_numeric_b:
                return 1
            # Both are non-numeric, compare lexically (ASCII order)
            else:
                if id_a < id_b:
                    return -1
                elif id_a > id_b:
                    return 1

        return 0

    major_a, minor_a, patch_a, pre_a = parse_version(a)
    major_b, minor_b, patch_b, pre_b = parse_version(b)

    # Compare core version
    if major_a != major_b:
        return -1 if major_a < major_b else 1
    if minor_a != minor_b:
        return -1 if minor_a < minor_b else 1
    if patch_a != patch_b:
        return -1 if patch_a < patch_b else 1

    # Core versions are equal, compare pre-release
    return compare_prerelease(pre_a, pre_b)
